custom_js = """
// =====================================================================
// Neural Growth Network - a self-growing branching network rendered
// on a single canvas, with glowing synapses and traveling pulses.
// Code is organized into: setup, GUI setup, growth, synapse detection,
// pulse animation, and rendering.
// =====================================================================

// ================= Setup =================
const canvas = document.getElementById('stage');
const ctx = canvas.getContext('2d');
const CX = canvas.width / 2;
const CY = canvas.height / 2;

// Palette values that are not exposed as user controls
const FIXED = {
  bgGlow: '#101a3a',
  grid: 'rgba(0, 229, 255, 0.08)'
};

// Tunable parameters bound to the GUI panel
const params = {
  neuronCount: 4,
  growthSpeed: 1.0,
  maxDepth: 6,
  splitChance: 0.35,
  curvature: 0.5,
  maxBranchLength: 70,
  synapseDistance: 36,
  synapseGlow: 18,
  pulseSpeed: 1.4,
  pulseFrequency: 0.03,
  pulseBrightness: 1.1,
  bgColor: '#05070f',
  branchColor: '#00e5ff',
  accentColor: '#d6ff00',
  synapseColor: '#ff2bd6',
  pulseColor: '#fff36a',
  paused: false,
  regenerate: function () { buildNetwork(); },
  clear: function () { clearScene(); },
  toggle: function () {
    params.paused = !params.paused;
    pauseCtrl.name(params.paused ? 'Resume animation' : 'Pause animation');
  }
};

// Simulation state - plain arrays/objects only, no external data structures
let branches = [];
let synapses = [];
let pulses = [];
let activeTips = [];
let synapseKeys = new Set();
let totalBranches = 0;
let growing = true;
let simTime = 0;
const MAX_BRANCHES = 140;

// ================= GUI setup =================
const gui = new dat.GUI({ width: 300 });

const fGrowth = gui.addFolder('Growth');
fGrowth.add(params, 'neuronCount', 3, 6, 1).name('neuron count');
fGrowth.add(params, 'growthSpeed', 0.1, 3, 0.1).name('growth speed');
fGrowth.add(params, 'maxDepth', 2, 10, 1).name('max branch depth');
fGrowth.add(params, 'splitChance', 0, 1, 0.01).name('branch split chance');
fGrowth.add(params, 'curvature', 0, 1, 0.01).name('branch curvature');
fGrowth.add(params, 'maxBranchLength', 20, 160, 1).name('max branch length');
fGrowth.open();

const fSyn = gui.addFolder('Synapses');
fSyn.add(params, 'synapseDistance', 10, 100, 1).name('distance threshold');
fSyn.add(params, 'synapseGlow', 0, 40, 1).name('glow strength');
fSyn.open();

const fPulse = gui.addFolder('Pulses');
fPulse.add(params, 'pulseSpeed', 0.2, 5, 0.1).name('pulse speed');
fPulse.add(params, 'pulseFrequency', 0, 0.2, 0.005).name('pulse frequency');
fPulse.add(params, 'pulseBrightness', 0.2, 2, 0.05).name('pulse brightness');
fPulse.open();

const fVisual = gui.addFolder('Visuals');
fVisual.addColor(params, 'bgColor').name('background color');
fVisual.addColor(params, 'branchColor').name('branch color');
fVisual.addColor(params, 'accentColor').name('accent branch color');
fVisual.addColor(params, 'synapseColor').name('synapse color');
fVisual.addColor(params, 'pulseColor').name('pulse color');
fVisual.open();

gui.add(params, 'regenerate').name('Regenerate network');
gui.add(params, 'clear').name('Clear canvas');
const pauseCtrl = gui.add(params, 'toggle').name('Pause animation');

// ================= Neuron growth =================
function rand(min, max) { return min + Math.random() * (max - min); }

// Create a single growing branch tip
function makeBranch(x, y, angle, depth, neuronId, kind, maxLen) {
  totalBranches++;
  return {
    points: [{ x: x, y: y }],
    x: x, y: y, angle: angle,
    depth: depth,
    length: 0,
    maxLength: maxLen,
    width: rand(1.0, 2.2),
    kind: kind, // 'main' or 'accent'
    neuronId: neuronId,
    alive: true
  };
}

// Reset and grow a fresh set of seed neurons near the canvas center
function buildNetwork() {
  branches = [];
  synapses = [];
  pulses = [];
  activeTips = [];
  synapseKeys.clear();
  totalBranches = 0;
  growing = true;

  const count = Math.round(params.neuronCount);
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2 + rand(-0.3, 0.3);
    const r = rand(10, 60);
    const nx = CX + Math.cos(a) * r;
    const ny = CY + Math.sin(a) * r;
    // two initial axon/dendrite lines per seed neuron
    for (let b = 0; b < 2; b++) {
      const angle = rand(0, Math.PI * 2);
      const br = makeBranch(nx, ny, angle, 0, i, 'main', params.maxBranchLength * rand(0.7, 1.1));
      branches.push(br);
      activeTips.push(br);
    }
  }
}

// Advance every growing branch tip by a small organic step each frame
function updateGrowth(dt) {
  if (!growing) return;
  const step = 1.6 * params.growthSpeed * dt;
  const stillActive = [];

  for (const br of activeTips) {
    if (!br.alive) continue;
    if (totalBranches >= MAX_BRANCHES) { br.alive = false; continue; }

    // slightly random organic curvature keeps the path smooth but alive
    br.angle += (Math.random() - 0.5) * params.curvature * 0.6;
    br.x += Math.cos(br.angle) * step;
    br.y += Math.sin(br.angle) * step;
    br.length += step;
    br.points.push({ x: br.x, y: br.y });
    br.width = Math.max(0.6, br.width + (Math.random() - 0.5) * 0.05);

    const outOfBounds = br.x < -20 || br.x > canvas.width + 20 || br.y < -20 || br.y > canvas.height + 20;

    if (br.length >= br.maxLength || br.depth >= params.maxDepth || outOfBounds) {
      br.alive = false; // this tip has finished growing
      continue;
    }

    // occasionally split into a new branching path
    if (Math.random() < params.splitChance * 0.04 && totalBranches < MAX_BRANCHES) {
      const child = makeBranch(br.x, br.y, br.angle + rand(-0.9, 0.9), br.depth + 1, br.neuronId, 'accent', br.maxLength * 0.7);
      branches.push(child);
      stillActive.push(child);
    }

    // occasionally sprout a smaller side branch for extra detail
    if (Math.random() < 0.01 && totalBranches < MAX_BRANCHES) {
      const side = makeBranch(br.x, br.y, br.angle + rand(-1.4, 1.4), br.depth + 2, br.neuronId, 'accent', br.maxLength * 0.35);
      branches.push(side);
      stillActive.push(side);
    }

    stillActive.push(br);
  }

  activeTips = stillActive;
  if (activeTips.filter(function (b) { return b.alive; }).length === 0) growing = false;
}

// ================= Synapse detection =================
// Connects nearby branch tips from different seed neurons, avoiding duplicates.
function updateSynapses() {
  const n = branches.length;
  const threshold = params.synapseDistance;
  for (let i = 0; i < n; i++) {
    const a = branches[i];
    if (a.points.length < 2) continue;
    for (let j = i + 1; j < n; j++) {
      const b = branches[j];
      if (b.points.length < 2 || a.neuronId === b.neuronId) continue;
      const key = i + '_' + j;
      if (synapseKeys.has(key)) continue;
      const dx = a.x - b.x, dy = a.y - b.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < threshold) {
        synapseKeys.add(key);
        synapses.push({ ax: a.x, ay: a.y, bx: b.x, by: b.y, phase: rand(0, Math.PI * 2) });
      }
    }
  }
}

// ================= Pulse animation =================
// Spawns short electric pulses that travel smoothly along random synapses.
function updatePulses(dt) {
  if (synapses.length === 0) return;
  if (Math.random() < params.pulseFrequency * dt * 2) {
    const s = synapses[Math.floor(Math.random() * synapses.length)];
    pulses.push({ s: s, t: 0, reverse: Math.random() < 0.5 });
  }
  const speed = 0.01 * params.pulseSpeed;
  pulses = pulses.filter(function (p) {
    p.t += speed * dt;
    return p.t < 1;
  });
  if (pulses.length > 60) pulses.splice(0, pulses.length - 60);
}

// ================= Rendering =================
function lerp(a, b, t) { return a + (b - a) * t; }

function drawBackground() {
  ctx.fillStyle = params.bgColor;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const glow = ctx.createRadialGradient(CX, CY, 40, CX, CY, 480);
  glow.addColorStop(0, FIXED.bgGlow);
  glow.addColorStop(1, 'rgba(16, 26, 58, 0)');
  ctx.save();
  ctx.globalAlpha = 0.6;
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.restore();
}

function drawGrid() {
  ctx.save();
  ctx.strokeStyle = FIXED.grid;
  ctx.lineWidth = 1;
  const offset = (simTime * 6) % 4;
  for (let y = -4 + offset; y < canvas.height; y += 4) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }
  // sparse gritty noise specks, redrawn fresh each frame (no stored particles)
  ctx.fillStyle = FIXED.grid;
  for (let i = 0; i < 25; i++) {
    ctx.fillRect(Math.random() * canvas.width, Math.random() * canvas.height, 1, 1);
  }
  ctx.restore();
}

function drawBranches() {
  for (const br of branches) {
    const pts = br.points;
    if (pts.length < 2) continue;
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    // lightweight smoothing: quadratic curve through midpoints
    for (let i = 1; i < pts.length - 1; i++) {
      const mx = (pts[i].x + pts[i + 1].x) / 2;
      const my = (pts[i].y + pts[i + 1].y) / 2;
      ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
    }
    const last = pts[pts.length - 1];
    ctx.lineTo(last.x, last.y);
    ctx.strokeStyle = br.kind === 'accent' ? params.accentColor : params.branchColor;
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 9;
    ctx.lineWidth = br.width;
    ctx.stroke();
  }
}

function drawSynapses() {
  for (const s of synapses) {
    const pulseAmt = 0.6 + 0.4 * Math.sin(simTime * 2 + s.phase);
    // faint connecting thread between the two branch tips
    ctx.beginPath();
    ctx.moveTo(s.ax, s.ay);
    ctx.lineTo(s.bx, s.by);
    ctx.strokeStyle = params.synapseColor;
    ctx.globalAlpha = 0.18;
    ctx.lineWidth = 1;
    ctx.shadowBlur = params.synapseGlow * 0.3;
    ctx.shadowColor = params.synapseColor;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // bright glowing synapse node, pulsing softly over time
    const mx = (s.ax + s.bx) / 2, my = (s.ay + s.by) / 2;
    ctx.beginPath();
    ctx.arc(mx, my, 2.6, 0, Math.PI * 2);
    ctx.fillStyle = params.synapseColor;
    ctx.shadowBlur = params.synapseGlow * pulseAmt;
    ctx.shadowColor = params.synapseColor;
    ctx.fill();
  }
}

function drawPulses() {
  for (const p of pulses) {
    const t = p.reverse ? 1 - p.t : p.t;
    const x = lerp(p.s.ax, p.s.bx, t);
    const y = lerp(p.s.ay, p.s.by, t);
    ctx.beginPath();
    ctx.arc(x, y, 2.4, 0, Math.PI * 2);
    ctx.fillStyle = params.pulseColor;
    ctx.shadowColor = params.pulseColor;
    ctx.shadowBlur = 16 * params.pulseBrightness;
    ctx.globalAlpha = Math.min(1, params.pulseBrightness);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
}

function drawVignette() {
  const vg = ctx.createRadialGradient(CX, CY, 260, CX, CY, 560);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.8)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function render() {
  ctx.shadowBlur = 0;
  drawBackground();
  drawGrid();
  drawBranches();
  drawSynapses();
  drawPulses();
  drawVignette();
}

function clearScene() {
  branches = [];
  synapses = [];
  pulses = [];
  activeTips = [];
  synapseKeys.clear();
  totalBranches = 0;
  growing = false;
}

// ================= Main loop =================
let lastTs = performance.now();
function animate(now) {
  const dt = Math.min((now - lastTs) / 16.6667, 3);
  lastTs = now;
  simTime += dt * 0.016;

  if (!params.paused) {
    updateGrowth(dt);
    if (growing) updateSynapses();
    updatePulses(dt);
  }
  render();
  requestAnimationFrame(animate);
}

buildNetwork();
requestAnimationFrame(animate);
